draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2*Math.PI); // head
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 100); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 80, H/2 + 80); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 120, H/2 + 80); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 90, H/2 + 130); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 110, H/2 + 130); // leg
  ctx.stroke();

  // draw speech bubble
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 + 150, H/2 - 50, 30 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Eat me!', W/2 + 150, H/2 - 50);

  ctx.restore();
}
